import json
import os

def get_port():
    file_path = "/safe/config.json"
    default_port = 8080

    if not os.path.exists(file_path):
        return default_port

    try:
        with open(file_path, 'r') as file:
            config = json.load(file)
            return config.get("port", default_port)
    except (json.JSONDecodeError, IOError):
        return default_port
